CREATE TYPE "UserRole" AS ENUM ('SUPER_ADMIN', 'BUSINESS_OWNER', 'BUSINESS_ADMIN', 'STAFF', 'CUSTOMER');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'CUSTOMER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Business" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "BusinessMember" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "businessId" TEXT NOT NULL, "role" "UserRole" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BusinessMember_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, CONSTRAINT "BusinessMember_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "BusinessMember_userId_businessId_key" ON "BusinessMember"("userId", "businessId"); CREATE INDEX "BusinessMember_businessId_role_idx" ON "BusinessMember"("businessId", "role");
CREATE TABLE "RefreshSession" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "RefreshSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "RefreshSession_userId_idx" ON "RefreshSession"("userId"); CREATE INDEX "RefreshSession_expiresAt_idx" ON "RefreshSession"("expiresAt");
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Customer_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "Customer_userId_key" ON "Customer"("userId");
CREATE TABLE "Location" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "Location_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE); CREATE INDEX "Location_businessId_idx" ON "Location"("businessId");
CREATE TABLE "Staff" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL, "locationId" TEXT, "userId" TEXT, CONSTRAINT "Staff_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE, CONSTRAINT "Staff_locationId_fkey" FOREIGN KEY ("locationId") REFERENCES "Location"("id") ON DELETE SET NULL); CREATE UNIQUE INDEX "Staff_businessId_userId_key" ON "Staff"("businessId", "userId"); CREATE INDEX "Staff_businessId_locationId_idx" ON "Staff"("businessId", "locationId");
CREATE TABLE "Service" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "Service_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE); CREATE INDEX "Service_businessId_idx" ON "Service"("businessId");
CREATE TABLE "Appointment" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL, "customerId" TEXT NOT NULL, "serviceId" TEXT NOT NULL, "staffId" TEXT, "startsAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Appointment_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT, CONSTRAINT "Appointment_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT, CONSTRAINT "Appointment_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE RESTRICT, CONSTRAINT "Appointment_staffId_fkey" FOREIGN KEY ("staffId") REFERENCES "Staff"("id") ON DELETE SET NULL); CREATE INDEX "Appointment_businessId_startsAt_idx" ON "Appointment"("businessId", "startsAt"); CREATE INDEX "Appointment_customerId_startsAt_idx" ON "Appointment"("customerId", "startsAt"); CREATE INDEX "Appointment_staffId_startsAt_idx" ON "Appointment"("staffId", "startsAt");
CREATE TABLE "Review" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL, "customerId" TEXT NOT NULL, "rating" INTEGER NOT NULL, CONSTRAINT "Review_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE, CONSTRAINT "Review_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE); CREATE INDEX "Review_businessId_idx" ON "Review"("businessId"); CREATE INDEX "Review_customerId_idx" ON "Review"("customerId");
